values = {"name": "web", "image": "web:1.4.0", "replicas": 3, "port": 8080}

template = """apiVersion: apps/v1
kind: Deployment
metadata:
  name: {name}
spec:
  replicas: {replicas}
  template:
    spec:
      containers:
        - name: {name}
          image: {image}
          ports:
            - containerPort: {port}"""


def render(template, values):
    return template.format(**values)


def install(release_name, values, overrides=None):
    merged = dict(values)
    if overrides:
        merged.update(overrides)
    return render(template, merged)


print(install("web-prod", values))
print("---")
print(install("web-staging", values, {"replicas": 1, "image": "web:1.5.0-rc1"}))
